import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: {project_basename: {framework: {pkg_id: resolved_version}}}
def build_lookup(data):
    lookup = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        lookup[name] = {}
        for fw in proj['frameworks']:
            lookup[name][fw['framework']] = {p['id']: p['resolvedVersion'] for p in fw['topLevelPackages']}
    return lookup

b = build_lookup(baseline)
a = build_lookup(after)

changes = []
unchanged = []

for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    for fw in sorted(set(list(b.get(proj,{}).keys()) + list(a.get(proj,{}).keys()))):
        bp = b.get(proj,{}).get(fw,{})
        ap = a.get(proj,{}).get(fw,{})
        for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
            bv = bp.get(pkg)
            av = ap.get(pkg)
            label = f'{proj} ({fw})'
            if bv and av and bv == av:
                unchanged.append((label, pkg, av))
            elif bv and av and bv != av:
                changes.append((label, pkg, bv, av, 'Aligned to highest version'))
            elif bv and not av:
                changes.append((label, pkg, bv, '-', 'Removed'))
            elif not bv and av:
                changes.append((label, pkg, '-', av, 'Added'))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'  {c[0]} | {c[1]} | {c[2]} -> {c[3]} | {c[4]}')
else:
    print('  None')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'  {u[0]} | {u[1]} | {u[2]}')
"

